const body = $input.first().json.body || $input.first().json;
const entry = (body.entry || [])[0] || {};
const msg = (entry.messaging || [])[0] || {};
return [{ json: {
  sender_id: (msg.sender && msg.sender.id) || '',
  texte: (msg.message && msg.message.text) || '',
  page_id: (msg.recipient && msg.recipient.id) || ''
} }];

const cur = $('Extraire message').first().json;
const profil = $('FB - Profil client').first().json;
const lignes = $('Lire Conversations').all().map(i => i.json);
const ligne = lignes.find(r => String(r.psid) === String(cur.sender_id));
return [{ json: {
  sender_id: cur.sender_id, texte: cur.texte,
  prenom: profil.first_name || '', nom: profil.last_name || '',
  historique_json: (ligne && ligne.historique_json) || '[]',
  conversation_existe: !!ligne
} }];

const raw = $('Gemini - Conseil Messenger').first().json;
let texte = '';
try { texte = raw.candidates[0].content.parts.map(p => p.text || '').join(''); } catch (e) { texte = ''; }
const m = texte.match(/\{[ \n]*"commande_complete"[^\n]*\}/);
let commande = null;
if (m) { try { commande = JSON.parse(m[0]); } catch (e) { commande = null; } }
let texte_client = commande ? texte.slice(0, m.index).trim() : texte.trim();
if (!texte_client) texte_client = texte.trim();
return [{ json: { texte_client, commande_complete: !!commande, commande: commande || {} } }];

const ctx = $('Preparer contexte').first().json;
const rep = $('Parser reponse').first().json;
let hist = [];
try { hist = JSON.parse(ctx.historique_json || '[]'); } catch (e) { hist = []; }
hist.push({ role: 'client', texte: ctx.texte });
hist.push({ role: 'moi_ai', texte: rep.texte_client });
if (rep.commande_complete) hist.push({ role: 'commande', detail: rep.commande });
return [{ json: { psid: ctx.sender_id, historique_json: JSON.stringify(hist), statut: rep.commande_complete ? 'commande' : 'en_cours' } }];
